__NUXT_JSONP__("/jp/school-calendar", {data:[{details:{slug:"jp",pageTitle:"スクールカレンダー（学校開始日） | Mentor Language Institute",pageDescription:"コース開始日は、学生（F)ビザ就学生と、取得しない生徒で異なります。",title:"スクールカレンダー（学校開始日）",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003E黄色\u003C\u002Ffont\u003E：プログラム（学期）のスタート日\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003E緑色\u003C\u002Ffont\u003E：学校が休みの日"],schoolCalendar:{title:"コースの開始日",description:["コース開始日は、\u003Cspan class=\"ymarker\"\u003E学生（F)ビザ就学生と、取得しない生徒で異なります。\u003C\u002Fspan\u003E"],lists:[{key:"学生（F)ビザを取得しない生徒",value:["月曜日から授業を開始できます。　\u003Cbr \u002F\u003E*月曜日が祝日の場合は火曜日からの開始となります。"]},{key:"学生（F)ビザ就学生",value:["年間13回の学期はじまりから。※表の黄色マーク","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"現地に到着する日程について良くある質問",lists:[{key:"\u003Cb\u003EQ:授業開始の何日前からの入国が可能ですか？\u003C\u002Fb\u003E",value:["A:学校として入国する日に定めはありませんが、多くの留学生は授業開始する1~2日前から入国します。"],note:"注：学生（F)ビザを取得する方は、米国移民法により授業を開始する30日前から入国する事が可能です"},{key:"\u003Cb\u003EQ:授業開始するよりも早くに滞在先だけを手配することは可能ですか？\u003C\u002Fb\u003E",value:["A:はい。ビザなどの諸条件が許せば、滞在だけを先に手配する、学校の開始を1週間遅らせると言った対応は可能です。\u003Cbr \u002F\u003Eその他質問などがございましたらお気軽にご相談ください。"]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:30.877Z",updatedAt:"2026-04-24T11:47:24.306Z"}}],fetch:{},mutations:void 0});